//DEPS org.springframework:spring-context:6.1.14
import org.springframework.context.annotation.*;
import org.springframework.beans.factory.annotation.Value;
public class Lesson {
record Score(int value) {}
record Badge(Score score) { int value() { return score.value() * 2; } }
@Configuration
static class Config {
@Bean Score score() { return new Score(4); }
@Bean Badge badge(Score score) { return new Badge(score); }
}
public static void main(String[] args) {
 try (var context = new AnnotationConfigApplicationContext(Config.class)) {
System.out.println(context.getBean(Badge.class).value());
 }
}
}

